package com.example.notification_service.service;import com.example.notification_service.event.ApplicationEvent;import org.springframework.stereotype.Service;
@Service public class EmailTemplateService{public EmailMessage render(ApplicationEvent event){String job=safe(event.data().jobTitle());return switch(event.eventType()){case "APPLICATION_SUBMITTED"->new EmailMessage("APPLICATION_SUBMITTED","Application received: "+job,"Your application for "+job+" has been received.");case "APPLICATION_STATUS_CHANGED"->new EmailMessage("APPLICATION_STATUS_CHANGED","Application status updated: "+job,"Your application for "+job+" changed from "+safe(event.data().oldStatus())+" to "+safe(event.data().newStatus())+".");default->throw new IllegalArgumentException("Unsupported event type");};}private String safe(String value){if(value==null)return "";return value.replace('\r',' ').replace('\n',' ').substring(0,Math.min(150,value.length()));}public record EmailMessage(String templateCode,String subject,String body){}}
